     3→import { useState, useCallback, useRef } from "react";
     4→import { Activity } from "@/lib/mockData";
     5→
     6→const ALLOWED_EXTENSIONS = /\.(gpx|fit)$/i;
     7→
     8→interface UploadZoneProps {
     9→  onActivityAdded: (activity: Activity) => void;
    10→}
    11→
    12→export default function UploadZone({ onActivityAdded }: UploadZoneProps) {
    13→  const [isDragging, setIsDragging] = useState(false);
    14→  const [isUploading, setIsUploading] = useState(false);
    15→  const [lastResult, setLastResult] = useState<string | null>(null);
    16→  const inputRef = useRef<HTMLInputElement>(null);
    17→
    18→  const uploadFile = useCallback(
    19→    async (file: File) => {
    20→      if (!ALLOWED_EXTENSIONS.test(file.name)) {
    21→        setLastResult("✗ Unsupported file type. Please upload a .gpx or .fit file.");
    22→        return;
    23→      }
    24→
    25→      setIsUploading(true);
    26→      setLastResult(null);
    27→
    28→      const formData = new FormData();
    29→      formData.append("file", file);
    30→
    31→      try {
    32→        const res = await fetch("/api/activities/upload", {
    33→          method: "POST",
    34→          body: formData,
    35→        });
    36→
    37→        if (!res.ok) throw new Error("Upload failed");
    38→
    39→        const data = await res.json();
    40→
    41→        const newActivity: Activity = {
    42→          id: data.id,
    43→          date: data.date,
    44→          routeName: file.name.replace(ALLOWED_EXTENSIONS, ""),
    45→          distance: data.distance,
    46→          duration: data.duration,
    47→          elevation: data.elevation,
    48→        };
    49→
    50→        onActivityAdded(newActivity);
    51→        setLastResult(`✓ Parsed: ${data.distance.toFixed(1)} km, ${data.elevation} m elevation`);
    52→      } catch {
    53→        setLastResult("✗ Upload failed. Please try again.");
    54→      } finally {
    55→        setIsUploading(false);
    56→      }
    57→    },
    58→    [onActivityAdded]
    59→  );
    60→
    61→  const handleDrop = useCallback(
    62→    (e: React.DragEvent) => {
    63→      e.preventDefault();
    64→      setIsDragging(false);
    65→      const file = e.dataTransfer.files[0];
    66→      if (file) uploadFile(file);
    67→    },
    68→    [uploadFile]
    69→  );
    70→
    71→  const handleDragOver = useCallback((e: React.DragEvent) => {
    72→    e.preventDefault();
    73→    setIsDragging(true);
    74→  }, []);
    75→
    76→  const handleDragLeave = useCallback(() => {
    77→    setIsDragging(false);
    78→  }, []);
    79→
    80→  const handleChange = useCallback(
    81→    (e: React.ChangeEvent<HTMLInputElement>) => {
    82→      const file = e.target.files?.[0];
    83→      if (file) uploadFile(file);
    84→      e.target.value = "";
    85→    },
    86→    [uploadFile]
    87→  );
    88→
    89→  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    90→    if (e.key === "Enter" || e.key === " ") {
    91→      e.preventDefault();
    92→      inputRef.current?.click();
    93→    }
    94→  }, []);
    95→
    96→  return (
    97→    <div className="space-y-3">
    98→      <div
    99→        role="button"
   100→        tabIndex={0}
   101→        onDrop={handleDrop}
   102→        onDragOver={handleDragOver}
   103→        onDragLeave={handleDragLeave}
   104→        onClick={() => inputRef.current?.click()}
   105→        onKeyDown={handleKeyDown}
   106→        aria-label="Upload GPX or FIT file"
   107→        className={`
   108→          border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all
   109→          focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:ring-offset-gray-900
   110→          ${isDragging
   111→            ? "border-blue-500 bg-blue-500/10"
   112→            : "border-gray-700 hover:border-gray-500 hover:bg-gray-800/30"
   113→          }
   114→        `}
   115→      >
   116→        <input
   117→          ref={inputRef}
   118→          type="file"
   119→          accept=".gpx,.fit"
   120→          className="hidden"
   121→          onChange={handleChange}
   122→        />
   123→        <div className="text-3xl mb-2">{isUploading ? "⏳" : "📁"}</div>
   124→        {isUploading ? (
   125→          <p className="text-sm text-gray-400">Uploading and parsing…</p>
   126→        ) : (
   127→          <>
   128→            <p className="text-sm text-gray-300 font-medium">
   129→              Drop a GPX or FIT file here
   130→            </p>
   131→            <p className="text-xs text-gray-500 mt-1">or click to browse</p>
   132→          </>
   133→        )}
   134→      </div>
   135→      {lastResult && (
   136→        <p
   137→          className={`text-xs px-3 py-2 rounded-lg ${
   138→            lastResult.startsWith("✓")
   139→              ? "bg-green-900/30 text-green-400 border border-green-800"
   140→              : "bg-red-900/30 text-red-400 border border-red-800"
   141→          }`}
   142→        >
   143→          {lastResult}
   144→        </p>
   145→      )}
   146→    </div>
   147→  );
   148→}
